#!/usr/bin/env bash
#
# Response gate for the HTTP transcripts the chapters quote.
#
# A chapter that shows what a running service answers prints a transcript of
# `curl` requests against `bynk dev`, each followed by the status and body.
# Those bodies are generated by the compiler (the admission checks at the
# route), so a release that changes them makes the page wrong while every
# source gate stays green. This serves each project named by an `http` row of
# snippets/TRANSCRIPTS.tsv with `bynk dev` on a free port, replays each request,
# and compares the status and body exactly.
#
# The transcript format: a request is a `$ curl ...` line, continued with a
# trailing backslash, targeting localhost:8787 (or, for a project with several
# contexts, the next ports up, one per context in the order of their names). The next line is the status, a
# space, and the body, or the status alone for an empty body; further indented
# lines continue the body, which the page wraps to fit. Unwrapping strips each
# continuation line's indentation and joins it with nothing. Requests are separated by blank lines. The command is split
# into words by xargs, which honours the shell's quotes; it is never evaluated.
#
# A row may give a fourth column: arguments for `wrangler dev`, passed after
# `--`, such as `--var AUTH_JWT_SECRET:not-a-secret` for a project whose actors
# verify tokens. Split on spaces; no quoting.
#
# A transcript may have a sidecar file beside it, the same name with `.env` for
# `.txt`: `KEY=VALUE` lines whose values replace `$KEY` and `${KEY}` in the
# requests before they are split. It lets a page print `Bearer $ALICE` where
# the request needs a whole signed token. The answers are not substituted.
#
# `bynk dev` runs on a copy (it writes .bynk/dev/ into the project) and in its
# own process group: it starts wrangler through npx, and wrangler starts
# workerd, and those survive a kill of `bynk dev` alone. The whole group is
# stopped after each project and on exit.
#
# Needs `bynk`, `curl` and Node 22 or later (for wrangler) on PATH.

set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SNIPPETS="$ROOT/snippets"
TRANSCRIPTS="$SNIPPETS/TRANSCRIPTS.tsv"
QUOTED_HOST="localhost:8787"
READY_TIMEOUT="${READY_TIMEOUT:-180}"

BYNKC="${BYNKC:-$(command -v bynkc || true)}"
BYNK="${BYNK:-}"
if [ -z "$BYNK" ] && [ -n "$BYNKC" ] && [ -x "$(dirname "$BYNKC")/bynk" ]; then
  BYNK="$(dirname "$BYNKC")/bynk"
fi
BYNK="${BYNK:-$(command -v bynk || true)}"
if [ -z "$BYNK" ] || [ ! -x "$BYNK" ]; then
  echo "bynk not found on PATH. Install the Bynk toolchain (see README.md)," >&2
  echo "or set BYNK=/path/to/bynk." >&2
  exit 2
fi
printf 'Replaying quoted responses against %s dev\n\n' \
  "$("$BYNK" --version 2>/dev/null || printf '%s' "$BYNK")"

work="$(mktemp -d)"
pgid=""

stop_server() {
  [ -n "$pgid" ] || return 0
  kill -TERM -- "-$pgid" 2>/dev/null
  for _ in $(seq 1 50); do
    kill -0 -- "-$pgid" 2>/dev/null || break
    sleep 0.1
  done
  kill -KILL -- "-$pgid" 2>/dev/null
  wait "$pgid" 2>/dev/null
  pgid=""
}
trap 'stop_server; rm -rf "$work"' EXIT
trap 'exit 130' INT TERM

# Prints the first of $1 consecutive free ports, none of them below $2 + 16 or
# within 16 of $2 when $2 is given. `bynk dev` gives each context its own port
# from a base, and its inspector its own from another, so a free base alone is
# not enough on a busy machine.
free_ports() {
  node -e '
    const net = require("net");
    const want = Number(process.argv[1]), avoid = Number(process.argv[2] || 0);
    const free = (port) => new Promise((ok) => {
      const s = net.createServer();
      s.once("error", () => ok(false));
      s.listen(port, "127.0.0.1", () => s.close(() => ok(true)));
    });
    const any = () => new Promise((ok) => {
      const s = net.createServer();
      s.listen(0, "127.0.0.1", () => { const p = s.address().port; s.close(() => ok(p)); });
    });
    (async () => {
      for (;;) {
        const base = await any();
        if (avoid && Math.abs(base - avoid) < 16) continue;
        if (base + want > 65535) continue;
        let ok = true;
        for (let i = 0; i < want && ok; i++) ok = await free(base + i);
        if (ok) { console.log(base); return; }
      }
    })();
  ' "$1" "${2:-0}"
}

# Starts `bynk dev` for $1 on port $2, logging to $3, with the wrangler
# arguments in $4, for a project of $5 contexts; returns once it is ready.
start_server() {
  local -a extra=()
  if [ -n "${4:-}" ]; then
    read -ra extra <<<"$4"
    extra=(-- "${extra[@]}")
  fi
  # Several contexts each start a wrangler inspector, and without --inspect
  # they collide on 9229 and fail to start (bynk-lang/bynk#1954).
  local inspect
  inspect="$(free_ports "$5" "$2")"
  # Local Service Bindings find each other through wrangler's dev registry,
  # by Worker name. A shared registry lets one project's bindings resolve to
  # another run's Workers of the same name, a previous chapter's or another
  # session's, so each project gets a registry of its own.
  local registry
  registry="$(mktemp -d "$work/registry.XXXXXX")"
  set -m
  WRANGLER_REGISTRY_PATH="$registry" WRANGLER_SEND_METRICS=false \
    "$BYNK" dev --base-port "$2" \
    --inspect --inspect-port "$inspect" "$1" "${extra[@]}" >"$3" 2>&1 &
  pgid=$!
  set +m
  local n want
  for _ in $(seq 1 "$READY_TIMEOUT"); do
    want="$(sed -n 's/^bynk dev: serving \([0-9]*\) context.*/\1/p' "$3" | head -1)"
    n="$(grep -c 'Ready on http://localhost:' "$3")"
    if [ -n "$want" ] && [ "$n" -ge "$want" ]; then
      # A Service Binding can refuse its first call until the binding has
      # connected; give a multi-context project a moment to settle.
      [ "$want" -le 1 ] || sleep 3
      return 0
    fi
    kill -0 "$pgid" 2>/dev/null || return 1
    sleep 1
  done
  return 1
}

# Replays the transcript $1 against port $2. Prints one line per mismatch.
replay() {
  local transcript="$1" port="$2"
  local expected="" state=gap line key value
  local -a vars=()
  if [ -f "${transcript%.txt}.env" ]; then
    while IFS= read -r line || [ -n "$line" ]; do
      case "$line" in '' | \#*) continue ;; esac
      vars+=("$line")
    done <"${transcript%.txt}.env"
  fi
  local -a requests=() answers=()
  while IFS= read -r line || [ -n "$line" ]; do
    if [ -z "$line" ]; then
      state=gap
      continue
    fi
    case "$state" in
    gap)
      if [ "${line#\$ }" = "$line" ]; then
        echo "expected a \`\$ curl\` line, got: $line"
        return
      fi
      requests+=("${line#\$ }")
      answers+=("")
      state=cmd
      ;;
    cmd)
      requests[${#requests[@]} - 1]+="$line"
      ;;
    answer)
      answers[${#answers[@]} - 1]="$line"
      state=body
      continue
      ;;
    body)
      answers[${#answers[@]} - 1]+="${line#"${line%%[![:space:]]*}"}"
      continue
      ;;
    esac
    # A command line ending in a backslash continues; otherwise the answer
    # comes next.
    if [ "${line%\\}" = "$line" ]; then
      state=answer
    else
      requests[${#requests[@]} - 1]="${requests[${#requests[@]} - 1]%\\}"
    fi
  done <"$transcript"

  if [ "${#requests[@]}" -eq 0 ]; then
    echo "no requests found"
    return
  fi

  local i word body code actual
  local -a words args
  for i in "${!requests[@]}"; do
    expected="${answers[$i]}"
    for line in "${vars[@]}"; do
      key="${line%%=*}"
      value="${line#*=}"
      requests[$i]="${requests[$i]//\$\{$key\}/$value}"
      requests[$i]="${requests[$i]//\$$key/$value}"
    done
    if ! mapfile -d '' words < <(printf '%s' "${requests[$i]}" | xargs printf '%s\0'); then
      echo "cannot split: ${requests[$i]}"
      continue
    fi
    if [ "${words[0]:-}" != curl ]; then
      echo "not a curl request: ${requests[$i]}"
      continue
    fi
    args=()
    for word in "${words[@]:1}"; do
      # A project with several contexts serves them on consecutive ports from
      # 8787, in the order of their names; keep each request's offset.
      if [[ "$word" =~ ^localhost:([0-9]+)(.*)$ ]] &&
        [ "${BASH_REMATCH[1]}" -ge 8787 ] && [ "${BASH_REMATCH[1]}" -lt 8800 ]; then
        args+=("127.0.0.1:$((port + BASH_REMATCH[1] - 8787))${BASH_REMATCH[2]}")
      else
        args+=("$word")
      fi
    done
    if [ "${args[*]}" = "${words[*]:1}" ]; then
      echo "does not target $QUOTED_HOST: ${requests[$i]}"
      continue
    fi
    body="$work/body"
    : >"$body"
    code="$(curl -sS --max-time 30 -o "$body" -w '%{http_code}' "${args[@]}" 2>&1)"
    actual="$code"
    [ ! -s "$body" ] || actual+=" $(cat "$body")"
    if [ "$actual" != "$expected" ]; then
      printf '%s\n  quoted:   %s\n  answered: %s\n' "${requests[$i]}" "$expected" "$actual"
    fi
  done
  printf 'requests=%s\n' "${#requests[@]}"
}

fail=0
checked=0
while IFS=$'\t' read -r t k p w; do
  case "$t" in '' | \#*) continue ;; esac
  [ "$k" = http ] || continue
  checked=$((checked + 1))

  if [ ! -f "$SNIPPETS/$t" ] || [ ! -f "$SNIPPETS/$p/bynk.toml" ]; then
    printf 'FAIL    %-42s %s\n' "$t" "transcript or project $p missing"
    fail=1
    continue
  fi

  copy="$work/${p//\//__}"
  rm -rf "$copy" && mkdir -p "$copy" && cp -R "$SNIPPETS/$p/." "$copy/"
  rm -rf "$copy/out" "$copy/out-js" "$copy/.bynk"
  log="$work/dev.log"
  contexts="$(grep -rlE '^context ' "$copy/src" 2>/dev/null | wc -l)"
  [ "$contexts" -ge 1 ] || contexts=1
  port="$(free_ports "$contexts")"

  # A port can still be taken between choosing it and binding it, on a busy
  # machine, so try a second set before giving up.
  started=1
  if ! start_server "$copy" "$port" "$log" "${w:-}" "$contexts"; then
    stop_server
    port="$(free_ports "$contexts")"
    start_server "$copy" "$port" "$log" "${w:-}" "$contexts" || started=0
  fi
  if [ "$started" -eq 0 ]; then
    printf 'FAIL    %-42s %s\n' "$t" "bynk dev did not come up on port $port"
    sed 's/^/          | /' "$log"
    stop_server
    fail=1
    continue
  fi
  report="$(replay "$SNIPPETS/$t" "$port")"
  stop_server

  n="$(printf '%s\n' "$report" | sed -n 's/^requests=//p')"
  problems="$(printf '%s\n' "$report" | grep -v '^requests=')"
  if [ -n "$problems" ] || [ -z "$n" ]; then
    printf 'FAIL    %-42s %s\n' "$t" "the quoted responses no longer match"
    printf '%s\n' "$problems" | sed 's/^/          | /'
    fail=1
  else
    printf '  ok    %-42s %s requests against %s\n' "$t" "$n" "$p"
  fi
done < "$TRANSCRIPTS"

echo
if [ "$fail" -eq 0 ]; then
  echo "All $checked quoted HTTP transcripts match what bynk dev answers."
else
  echo "Some quoted responses no longer match. Revise the chapter's transcript"
  echo "to what the server answers now, rewrapped to fit the page."
fi
exit "$fail"
